urlset:
{%- for locale, i18n_files in i18n_alternates.items() %}
{%- for file in i18n_files %}
    {%- if not file.page or file.page.is_link or file.locale != locale %}
        {%- continue %}
    {%- endif %}
    {%- set page_href = (file.page.canonical_url or file.page.abs_url or (config.site_url ~ file.url)) | e %}

        {{ page_href }}
    {%- if file.page.update_date %}
        {{ file.page.update_date }}
    {%- endif %}
        daily
    {%- set spravzhni = [] %}
    {%- for i18n_locale, i18n_file in file.alternates.items() if i18n_file.locale == i18n_locale %}
        {%- set _ = spravzhni.append(1) %}
    {%- endfor %}
    {%- if spravzhni | length > 1 %}
    {%- for i18n_locale, i18n_file in file.alternates.items() if i18n_file.locale == i18n_locale %}
        {%- if i18n_file.page and i18n_file.page.canonical_url %}
            {%- set i18n_href = i18n_file.page.canonical_url | e %}
        {%- elif i18n_file.url == "./" %}
            {%- set i18n_href = config.site_url %}
        {%- else %}
            {%- set i18n_href = config.site_url ~ i18n_file.url %}
        {%- endif %}

    {%- endfor %}
    {%- endif %}

{%- endfor %}
{%- endfor %}
